var (
	testChainID = ChainIdentity{DeploymentID: "0000000000F9PR1WNVDTEXS31Z", Cell: "gru", Environment: "production"}
	testChainAt = time.Date(2026, time.October, 5, 12, 0, 0, 0, time.UTC)
)

func testRootKey(t *testing.T) ed25519.PrivateKey {
	t.Helper()
	_, private, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	return private
}

func testRoots(t *testing.T, keys ...ed25519.PrivateKey) Keyring {
	t.Helper()
	publics := make([]ed25519.PublicKey, 0, len(keys))
	for _, key := range keys {
		publics = append(publics, key.Public().(ed25519.PublicKey))
	}
	roots, err := ParseKeyring(publics...)
	if err != nil {
		t.Fatal(err)
	}
	return roots
}

func rotate(t *testing.T, id ChainIdentity, verified VerifiedRoots, next []ed25519.PrivateKey, signers ...ed25519.PrivateKey) SignedRotation {
	t.Helper()
	publics := make([]ed25519.PublicKey, 0, len(next))
	for _, key := range next {
		publics = append(publics, key.Public().(ed25519.PublicKey))
	}
	rotation, err := NextRotation(verified, publics...)
	if err != nil {
		t.Fatal(err)
	}
	var signed SignedRotation
	for _, key := range signers {
		envelope, err := SignRotation(rotation, id, testChainAt, testChainAt.Add(time.Hour), key)
		if err != nil {
			t.Fatal(err)
		}
		signed.Signatures = append(signed.Signatures, envelope)
	}
	return signed
}

func mustVerifyChain(t *testing.T, genesis Keyring, chain RootChain) VerifiedRoots {
	t.Helper()
	verified, err := VerifyRootChain(genesis, testChainID, chain)
	if err != nil {
		t.Fatal(err)
	}
	return verified
}

func RotationPolicy() Policy { return Policy{MaxLifetime: MaxRotationLifetime, ClockSkew: time.Minute} }

// ChainIdentity binds a root chain to one deployment, cell and environment.
type ChainIdentity struct {
	DeploymentID string
	Cell         string
	Environment  string
}

// Rotation is the signed payload of one statement. Roots are the new set's
// canonical Base64 public keys, sorted by key ID.
type Rotation struct {
	Schema   string   `json:"schema"`

func RotationScope(id ChainIdentity, sequence uint64) Scope {
	return Scope{Domain: RotationDomain, DeploymentID: id.DeploymentID, Cell: id.Cell,
		Environment: id.Environment, Role: rotationRole, Slot: strconv.FormatUint(sequence, 10)}
}

// RootSetDigest is the SHA-256 of the set's sorted key IDs.
func RootSetDigest(roots Keyring) string {
	sum := sha256.Sum256([]byte(strings.Join(slices.Sorted(maps.Keys(roots)), "\n")))
	return hex.EncodeToString(sum[:])
}

// NextRotation builds the statement that replaces verified's current set
// with roots.
func NextRotation(verified VerifiedRoots, roots ...ed25519.PublicKey) (Rotation, error) {
	keyring, err := ParseKeyring(roots...)
	if err != nil {
		return Rotation{}, err
	}
	if len(keyring) > MaxRootSet {
		return Rotation{}, fmt.Errorf("%w: more than %d roots", ErrInvalid, MaxRootSet)
	}
	rotation := Rotation{Schema: RotationSchema, Sequence: verified.Sequence + 1, Previous: verified.Head}
	for _, keyID := range slices.Sorted(maps.Keys(keyring)) {
		rotation.Roots = append(rotation.Roots, base64.RawURLEncoding.EncodeToString(keyring[keyID]))
	}
	return rotation, nil
}

// SignRotation signs rotation with one old or new root.
func SignRotation(rotation Rotation, id ChainIdentity, issuedAt, expiresAt time.Time, key ed25519.PrivateKey) (Envelope, error) {
	if _, err := rotation.keyring(); err != nil {
		return Envelope{}, err
	}
	payload, err := EncodePayload(rotation)
	if err != nil {
		return Envelope{}, err
	}
	return Sign(payload, RotationScope(id, rotation.Sequence), issuedAt, expiresAt, key)
}

// Payload returns the statement every signature covers.
func (signed SignedRotation) Payload() (Rotation, error) {
	payload, err := signed.payload()
	if err != nil {
		return Rotation{}, err
	}
	return decodeRotation(payload)
}

// VerifyRootChain verifies every statement from genesis. It checks
// signatures and links, not whether the newest statement is still current;
// see RotationCurrent.
func VerifyRootChain(genesis Keyring, id ChainIdentity, chain RootChain) (VerifiedRoots, error) {
	if chain.Version != 1 || len(genesis) == 0 || len(genesis) > MaxRootSet || len(chain.Rotations) > MaxRotations {
		return VerifiedRoots{}, fmt.Errorf("%w: root chain genesis or length", ErrInvalid)
	}
	if err := RotationScope(id, 1).validate(); err != nil {
		return VerifiedRoots{}, err
	}
	verified := VerifiedRoots{Current: maps.Clone(genesis), Historical: maps.Clone(genesis), Head: RootSetDigest(genesis)}
	for index, signed := range chain.Rotations {
		next, payload, err := verifyRotation(signed, id, verified)
		if err != nil {
			return VerifiedRoots{}, fmt.Errorf("root rotation %d: %w", index+1, err)
		}
		sum := sha256.Sum256(payload)
		verified.Current, verified.Sequence, verified.Head = next, verified.Sequence+1, hex.EncodeToString(sum[:])
		maps.Copy(verified.Historical, next)
	}
	return verified, nil
}

func verifyRotation(signed SignedRotation, id ChainIdentity, previous VerifiedRoots) (Keyring, []byte, error) {
	if len(signed.Signatures) == 0 || len(signed.Signatures) > 2*MaxRootSet {
		return nil, nil, fmt.Errorf("%w: signature count", ErrInvalid)
	}
	payload, err := signed.payload()
	if err != nil {
		return nil, nil, err
	}
	rotation, err := decodeRotation(payload)
	if err != nil {
		return nil, nil, err
	}
	if rotation.Sequence != previous.Sequence+1 || rotation.Previous != previous.Head {
		return nil, nil, fmt.Errorf("%w: statement does not extend the verified chain", ErrInvalid)
	}
	next, err := rotation.keyring()
	if err != nil {
		return nil, nil, err
	}
	scope := RotationScope(id, rotation.Sequence)
	signers := map[string]bool{}
	for _, envelope := range signed.Signatures {
		key, ok := previous.Current[envelope.KeyID]
		if !ok {
			key, ok = next[envelope.KeyID]
		}
		if !ok {
			return nil, nil, ErrUntrustedKey
		}
		if signers[envelope.KeyID] {
			return nil, nil, fmt.Errorf("%w: duplicate rotation signer", ErrInvalid)
		}
		// Every signature must cover the same statement.
		if own, err := compactPayload(envelope.Payload); err != nil || !bytes.Equal(own, payload) {
			return nil, nil, fmt.Errorf("%w: signatures cover different statements", ErrInvalid)
		}
		if _, err := VerifyHistorical(envelope, scope, Keyring{envelope.KeyID: key}, RotationPolicy()); err != nil {
			return nil, nil, err
		}
		signers[envelope.KeyID] = true
	}
	old := 0
	for keyID := range previous.Current {
		if signers[keyID] {
			old++
		}
	}
	if old < len(previous.Current)/2+1 {
		return nil, nil, ErrRotationSigners
	}
	for keyID := range next {
		if !signers[keyID] {
			return nil, nil, ErrRotationSigners
		}
	}
	return next, payload, nil
}

// RotationCurrent requires every signature of a statement to be within its
// validity window at now, so a withheld statement cannot be applied late.
// It does not verify signatures; verify the chain first.
func RotationCurrent(signed SignedRotation, now time.Time) error {
	policy := RotationPolicy()
	for _, envelope := range signed.Signatures {
		if envelope.IssuedAt.Sub(now) > policy.ClockSkew {
			return ErrNotYetValid
		}
		if !now.Before(envelope.ExpiresAt) {
			return ErrExpired
		}
	}
	return nil
}

// Extends reports whether chain keeps every statement of prefix in order:
// adopting it neither forks nor rolls back the adopted chain.
func (chain RootChain) Extends(prefix RootChain) bool {
	if chain.Version != 1 || prefix.Version != 1 || len(chain.Rotations) < len(prefix.Rotations) {
		return false
	}
	for index, signed := range prefix.Rotations {
		left, leftErr := signed.payload()
		right, rightErr := chain.Rotations[index].payload()
		if leftErr != nil || rightErr != nil || !bytes.Equal(left, right) {
			return false
		}
	}
	return true
}

// EncodeRootChain emits the deterministic, bounded wire form.
func EncodeRootChain(chain RootChain) ([]byte, error) {
	if chain.Version != 1 {
		return nil, fmt.Errorf("%w: root chain requires version 1", ErrInvalid)
	}
	if chain.Rotations == nil {
		chain.Rotations = []SignedRotation{}
	}
	encoded, err := json.Marshal(chain, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode root chain: %w", err)
	}
	if len(encoded) > MaxRootChainBytes {
		return nil, fmt.Errorf("%w: root chain exceeds %d bytes", ErrInvalid, MaxRootChainBytes)
	}
	return encoded, nil
}

// DecodeRootChain strictly decodes the canonical wire form.
func DecodeRootChain(wire []byte) (RootChain, error) {
	var chain RootChain
	if err := protocol.DecodeStrict(wire, &chain, MaxRootChainBytes); err != nil {
		return RootChain{}, fmt.Errorf("decode root chain: %w", err)
	}
	canonical, err := EncodeRootChain(chain)
	if err != nil {
		return RootChain{}, err
	}
	if !bytes.Equal(canonical, wire) {
		return RootChain{}, fmt.Errorf("%w: root chain is not canonical", ErrInvalid)
	}
	return chain, nil
}

func (signed SignedRotation) payload() ([]byte, error) {
	if len(signed.Signatures) == 0 {
		return nil, fmt.Errorf("%w: unsigned rotation", ErrInvalid)
	}
	return compactPayload(signed.Signatures[0].Payload)
}

func decodeRotation(payload []byte) (Rotation, error) {
	var rotation Rotation
	if err := protocol.DecodeStrict(payload, &rotation, MaxPayloadBytes); err != nil {
		return Rotation{}, fmt.Errorf("decode root rotation: %w", err)
	}
	canonical, err := EncodePayload(rotation)
	if err != nil || !bytes.Equal(canonical, payload) {
		return Rotation{}, fmt.Errorf("%w: root rotation is not canonical", ErrInvalid)
	}
	return rotation, nil
}

// keyring checks the statement's shape and returns its root set.
func (rotation Rotation) keyring() (Keyring, error) {
	if rotation.Schema != RotationSchema || rotation.Sequence == 0 || len(rotation.Previous) != 64 ||
		len(rotation.Roots) == 0 || len(rotation.Roots) > MaxRootSet {
		return nil, fmt.Errorf("%w: root rotation shape", ErrInvalid)
	}
	if _, err := hex.DecodeString(rotation.Previous); err != nil || strings.ToLower(rotation.Previous) != rotation.Previous {
		return nil, fmt.Errorf("%w: root rotation previous digest", ErrInvalid)
	}
	keys := make([]ed25519.PublicKey, 0, len(rotation.Roots))
	previousID := ""
	for _, encoded := range rotation.Roots {
		key, err := base64.RawURLEncoding.Strict().DecodeString(encoded)
		if err != nil || len(key) != ed25519.PublicKeySize {
			return nil, fmt.Errorf("%w: root rotation public key", ErrInvalid)
		}
		keyID, err := KeyID(key)
		if err != nil || keyID <= previousID {
			return nil, fmt.Errorf("%w: root rotation keys must be sorted by key ID without repeats", ErrInvalid)
		}
		previousID = keyID
		keys = append(keys, key)
	}
	return ParseKeyring(keys...)
}

func KeyID(publicKey ed25519.PublicKey) (string, error) {
	return protocol.KeyID(publicKey)
}

// EncodePayload emits deterministic JSON for a signed payload.
func EncodePayload(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust payload: %w", err)
	}
	if err := validatePayload(encoded); err != nil {
		return nil, err
	}
	return encoded, nil
}

// Sign signs a strict, bounded JSON object for the exact supplied scope.
func Sign(payload []byte, scope Scope, issuedAt, expiresAt time.Time, privateKey ed25519.PrivateKey) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: invalid Ed25519 private key", ErrInvalid)
	}
	if err := scope.validate(); err != nil {
		return Envelope{}, err
	}
	compact, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validTime(issuedAt) || !validTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: invalid trust validity interval", ErrInvalid)
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: SchemaVersion,
		KeyID:         keyID,
		Scope:         scope,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		Payload:       compact,
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

func VerifyCurrent(envelope Envelope, expected Scope, keys Keyring, now time.Time, policy Policy) ([]byte, error) {
	if !validTime(now) || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Sub(now) > policy.ClockSkew {
		return nil, ErrNotYetValid
	}
	if !now.Before(envelope.ExpiresAt) {
		return nil, ErrExpired
	}
	return bytesClone(envelope.Payload), nil
}

// VerifyHistorical verifies scope, signature, key, and the bounded signed
// interval but deliberately makes no current-authorization claim.
func VerifyHistorical(envelope Envelope, expected Scope, keys Keyring, policy Policy) ([]byte, error) {
	if policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	return bytesClone(envelope.Payload), nil
}

func verifySignature(envelope Envelope, expected Scope, keys Keyring, maximumLifetime time.Duration) error {
	if err := envelope.validateShape(); err != nil {
		return err
	}
	if err := expected.validate(); err != nil {
		return err
	}
	if envelope.Scope != expected {
		return ErrScopeMismatch
	}
	if !envelope.ExpiresAt.After(envelope.IssuedAt) || envelope.ExpiresAt.Sub(envelope.IssuedAt) > maximumLifetime {
		return fmt.Errorf("%w: invalid or excessive trust validity interval", ErrInvalid)
	}
	publicKey, exists := keys[envelope.KeyID]
	if !exists {
		return ErrUntrustedKey
	}
	keyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if keyID != envelope.KeyID {
		return ErrKeyMismatch
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := decodeCanonicalSignature(envelope.Signature)
	if err != nil || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

func (envelope Envelope) validateShape() error {
	if envelope.SchemaVersion != SchemaVersion || !domainRE.MatchString(envelope.Scope.Domain) || envelope.KeyID == "" || envelope.Signature == "" ||
		!canonicalTime(envelope.IssuedAt) || !canonicalTime(envelope.ExpiresAt) {
		return fmt.Errorf("%w: envelope header", ErrInvalid)
	}
	if _, err := decodeCanonicalSignature(envelope.Signature); err != nil {
		return err
	}
	if err := envelope.Scope.validate(); err != nil {
		return err
	}
	_, err := compactPayload(envelope.Payload)
	return err
}

func (scope Scope) validate() error {
	if !domainRE.MatchString(scope.Domain) {
		return fmt.Errorf("%w: scope domain", ErrInvalid)
	}
	if scope.Domain == DelegationDomain && scope == delegationScope() {
		return nil
	}
	if !entityid.Valid(scope.DeploymentID) || !cellRE.MatchString(scope.Cell) ||
		!tokenRE.MatchString(scope.Environment) || !tokenRE.MatchString(scope.Role) || !slotRE.MatchString(scope.Slot) {
		return fmt.Errorf("%w: incomplete or invalid scope", ErrInvalid)
	}
	return nil
}

func delegationScope() Scope {
	return Scope{
		Domain: DelegationDomain, DeploymentID: DelegationDeploymentID, Cell: delegationCell,
		Environment: delegationEnvironment, Role: delegationRole, Slot: delegationSlot,
	}
}

func compactPayload(payload []byte) (jsontext.Value, error) {
	if len(payload) == 0 || len(payload) > MaxPayloadBytes || !utf8.Valid(payload) {
		return nil, fmt.Errorf("%w: payload is empty, invalid UTF-8, or too large", ErrInvalid)
	}
	value := jsontext.Value(payload).Clone()
	if err := value.Compact(jsontext.AllowDuplicateNames(false), jsontext.AllowInvalidUTF8(false)); err != nil {
		return nil, fmt.Errorf("%w: invalid payload JSON: %v", ErrInvalid, err)
	}
	if len(value) == 0 || value.Kind() != jsontext.Kind('{') {
		return nil, fmt.Errorf("%w: payload must be a JSON object", ErrInvalid)
	}
	return value, nil
}

func validatePayload(payload []byte) error {
	_, err := compactPayload(payload)
	return err
}

func signingMaterial(envelope Envelope) ([]byte, error) {
	payload, err := compactPayload(envelope.Payload)
	if err != nil {
		return nil, err
	}
	material := make([]byte, 0, len(signatureDomain)+256+sha256.Size)
	material = append(material, signatureDomain...)
	material = binary.BigEndian.AppendUint16(material, uint16(envelope.SchemaVersion))
	for _, field := range []string{
		envelope.KeyID, envelope.Scope.Domain, envelope.Scope.DeploymentID, envelope.Scope.Cell,
		envelope.Scope.Environment, envelope.Scope.Role, envelope.Scope.Slot,
		envelope.IssuedAt.Format(time.RFC3339Nano), envelope.ExpiresAt.Format(time.RFC3339Nano),
	} {
		if len(field) > 1<<16-1 {
			return nil, fmt.Errorf("%w: signed field exceeds limit", ErrInvalid)
		}
		material = binary.BigEndian.AppendUint16(material, uint16(len(field)))
		material = append(material, field...)
	}
	payloadDigest := sha256.Sum256(payload)
	material = append(material, payloadDigest[:]...)
	return material, nil
}

func validTime(value time.Time) bool {
	return !value.IsZero() && value.Year() >= 1 && value.Year() <= 9999
}

func canonicalTime(value time.Time) bool {
	return validTime(value) && value.Location() == time.UTC &&
		value.Format(time.RFC3339Nano) == value.UTC().Format(time.RFC3339Nano)
}

func decodeCanonicalSignature(encoded string) ([]byte, error) {
	signature, err := base64.RawURLEncoding.Strict().DecodeString(encoded)
	if err != nil || len(signature) != ed25519.SignatureSize || base64.RawURLEncoding.EncodeToString(signature) != encoded {
		return nil, ErrBadSignature
	}
	return signature, nil
}

func bytesClone(value []byte) []byte { return append([]byte(nil), value...) }

// DelegatedKeyID creates the key ID stored alongside a delegated public key.
func DelegatedKeyID(publicKey ed25519.PublicKey) (string, error) {
	return KeyID(publicKey)
}

// EncodeDelegatedPublicKey uses the canonical unpadded URL-safe Base64 form.
func EncodeDelegatedPublicKey(publicKey ed25519.PublicKey) (string, error) {
	if len(publicKey) != ed25519.PublicKeySize {
		return "", fmt.Errorf("%w: invalid Ed25519 public key", ErrInvalid)
	}
	return base64.RawURLEncoding.EncodeToString(publicKey), nil
}

// ParseKeyring validates baked-in root public keys and derives their full IDs.
func ParseKeyring(publicKeys ...ed25519.PublicKey) (Keyring, error) {
	keyring := make(Keyring, len(publicKeys))
	for _, publicKey := range publicKeys {
		keyID, err := KeyID(publicKey)
		if err != nil {
			return nil, err
		}
		if _, exists := keyring[keyID]; exists {
			return nil, fmt.Errorf("%w: duplicate trusted root", ErrInvalid)
		}
		keyring[keyID] = append(ed25519.PublicKey(nil), publicKey...)
	}
	if len(keyring) == 0 {
		return nil, fmt.Errorf("%w: empty trusted root set", ErrInvalid)
	}
	return keyring, nil

func KeyID(publicKey ed25519.PublicKey) (string, error) {
	if len(publicKey) != ed25519.PublicKeySize {
		return "", fmt.Errorf("%w: expected an Ed25519 public key", ErrInvalidEnvelope)
	}
	digest := sha256.Sum256(publicKey)
	return "sha256:" + hex.EncodeToString(digest[:]), nil
}

func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

func DiscoveryGenesis() (Keyring, error) {
	block, rest := pem.Decode(discoveryGenesisPEM)
	if block == nil || block.Type != "PUBLIC KEY" || len(rest) != 0 {
		return nil, errors.New("embedded discovery genesis public key is invalid")
	}
	parsed, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, err
	}
	key, ok := parsed.(ed25519.PublicKey)
	if !ok {
		return nil, errors.New("embedded discovery genesis is not Ed25519")
	}
	return ParseKeyring(key)
}

