func flySecrets(ctx context.Context, bundles BundleClient, vaultID, cell string, output io.Writer) error {
	projectID, err := readSecret(ctx, bundles, vaultID, cell, dashboard.ProjectIDKey)
	if err != nil {
		return err
	}
	region, _, _ := strings.Cut(cell, "-")
	settings := map[string]string{"TERRABASE_URL": APIURL(region), "TERRABASE_PROJECT_ID": projectID, "TERRABASE_DATABASE": dashboard.Database,
		"TS_AUTH_ISSUER": Issuer(region), "TS_AUTH_CLIENT_ID": DashboardClientID, "TS_AUTH_REDIRECT_URL": DashboardRedirectURI}
	result := map[string]any{"app": FlyApp, "settings": settings, "api_key_secret": SecretName(cell, dashboard.APIKeyKey),
		"client_secret_secret": SecretName(cell, EnvDashboardClientSecret), "staged": false}
	if os.Getenv("FLY_API_TOKEN") == "" {
		return printLine(output, result)
	}
	key, err := readSecret(ctx, bundles, vaultID, cell, dashboard.APIKeyKey)
	if err != nil {
		return err
	}
	// ts-auth secrets creates the client secret; a Vault prepared before it
	// existed needs that rerun, which keeps every existing secret.
	clientSecret, err := readSecret(ctx, bundles, vaultID, cell, EnvDashboardClientSecret)
	if err != nil {
		return fmt.Errorf("%w; create it with ts-orch ts-auth secrets --plan FILE, then rerun", err)
	}
	input := []byte("TERRABASE_API_KEY=" + key + "\nTS_AUTH_CLIENT_SECRET=" + clientSecret + "\n")
	for name, value := range settings {
		input = fmt.Appendf(input, "%s=%s\n", name, value)
	}
	defer clear(input)
	command := exec.CommandContext(ctx, "flyctl", "secrets", "import", "--app", FlyApp, "--stage")
	command.Stdin = bytes.NewReader(input)
	if reply, err := command.CombinedOutput(); err != nil {
		redacted := strings.NewReplacer(key, "[redacted]", clientSecret, "[redacted]").Replace(string(reply))
		return fmt.Errorf("flyctl secrets import: %w: %s", err, redacted)
	}
	result["staged"] = true
	return printLine(output, result)
}

// printLine writes value as one JSON line.
func printLine(output io.Writer, value any) error {
	if err := json.MarshalWrite(output, value); err != nil {
		return err
	}
	_, err := fmt.Fprintln(output)
	return err
}

func readSecret(ctx context.Context, client BundleClient, vaultID, cell, key string) (string, error) {
	return readBack(ctx, client, vaultID, cell, key, false)
}

// readBack reads and checks a secret that may have been created a moment ago.
func readBack(ctx context.Context, client BundleClient, vaultID, cell, key string, created bool) (string, error) {
	name := SecretName(cell, key)
	value, err := vaultsecret.ReadBack(ctx, client, vaultID, name, created)
	if err != nil {
		return "", err
	}
	if err := validSecret(key, value); err != nil {
		return "", errors.Join(fmt.Errorf("Vault secret %s", name), err)
	}
	return value, nil
}

var testTarget = Target{CompartmentID: "ocid1.compartment.oc1..control", VaultID: "ocid1.vault.oc1.sa-saopaulo-1.vault",
	KeyID: "ocid1.key.oc1.sa-saopaulo-1.key"}

// fakeVault keeps secrets in memory. ListSecrets ignores the name filter so
// that a test controls which page holds a match.
type fakeVault struct {
	t                   *testing.T
	items               []ocivault.SecretSummary
	pageSize            int
	bundles             map[string]ocisecrets.SecretBundleContentDetails
	createErr           error
	createErrAfterStore error
	lists               []ocivault.ListSecretsRequest
	creates             []ocivault.CreateSecretRequest
	reads               []ocisecrets.GetSecretBundleByNameRequest
}

func newVault(t *testing.T) *fakeVault {
	return &fakeVault{t: t, bundles: map[string]ocisecrets.SecretBundleContentDetails{}}
}

// withSecrets stores every secret of cell as a base64 bundle.
func (v *fakeVault) withSecrets(cell string, secrets map[string]string) *fakeVault {
	for key, value := range secrets {
		v.bundles[SecretName(cell, key)] = ocisecrets.Base64SecretBundleContentDetails{Content: new(base64.StdEncoding.EncodeToString([]byte(value)))}
	}
	return v
}

func (v *fakeVault) add(name string, state ocivault.SecretSummaryLifecycleStateEnum) string {
	id := "ocid1.vaultsecret.oc1.sa-saopaulo-1.amaaaa" + strconv.Itoa(len(v.items)+1)
	v.items = append(v.items, ocivault.SecretSummary{Id: new(id), SecretName: new(name), LifecycleState: state})
	return id
}

func (v *fakeVault) ListSecrets(_ context.Context, request ocivault.ListSecretsRequest) (ocivault.ListSecretsResponse, error) {
	v.lists = append(v.lists, request)
	start := 0
	if request.Page != nil {
		start, _ = strconv.Atoi(*request.Page)
	}
	end := len(v.items)
	if v.pageSize > 0 && start+v.pageSize < end {
		end = start + v.pageSize
	}
	response := ocivault.ListSecretsResponse{Items: v.items[start:end]}
	if end < len(v.items) {
		response.OpcNextPage = new(strconv.Itoa(end))
	}
	return response, nil
}

func (v *fakeVault) CreateSecret(_ context.Context, request ocivault.CreateSecretRequest) (ocivault.CreateSecretResponse, error) {
	v.creates = append(v.creates, request)
	if v.createErr != nil {
		return ocivault.CreateSecretResponse{}, v.createErr
	}
	details := request.CreateSecretDetails
	content, ok := details.SecretContent.(ocivault.Base64SecretContentDetails)
	if !ok || details.SecretName == nil || content.Content == nil {
		v.t.Errorf("create request %+v", details)
		return ocivault.CreateSecretResponse{}, errors.New("bad request")
	}
	id := v.add(*details.SecretName, ocivault.SecretSummaryLifecycleStateCreating)
	v.bundles[*details.SecretName] = ocisecrets.Base64SecretBundleContentDetails{Content: content.Content}
	if v.createErrAfterStore != nil {
		return ocivault.CreateSecretResponse{}, v.createErrAfterStore
	}
	return ocivault.CreateSecretResponse{Secret: ocivault.Secret{Id: new(id)}}, nil
}

func (v *fakeVault) GetSecretBundleByName(_ context.Context, request ocisecrets.GetSecretBundleByNameRequest) (ocisecrets.GetSecretBundleByNameResponse, error) {
	v.reads = append(v.reads, request)
	content, ok := v.bundles[*request.SecretName]
	if !ok {
		return ocisecrets.GetSecretBundleByNameResponse{}, errors.New("secret not found")
	}
	return ocisecrets.GetSecretBundleByNameResponse{SecretBundle: ocisecrets.SecretBundle{SecretBundleContent: content}}, nil
}

// stored decodes the bundle of name.
func (v *fakeVault) stored(name string) string {
	bundle, _ := v.bundles[name].(ocisecrets.Base64SecretBundleContentDetails)
	if bundle.Content == nil {
		v.t.Fatalf("no secret %s", name)
	}
	value, err := base64.StdEncoding.DecodeString(*bundle.Content)
	if err != nil {
		v.t.Fatal(err)
	}
	return string(value)
}

func Name(scope, key string) string {
	return scope + "-" + strings.ToLower(strings.ReplaceAll(key, "_", "-"))
}

func Read(ctx context.Context, client BundleClient, vaultID, name string) (string, error) {
	response, err := readBundle(ctx, client, vaultID, name)
	if err != nil {
		return "", err
	}
	return decodeBundle(response.SecretBundle, name)
}

func readBundle(ctx context.Context, client BundleClient, vaultID, name string) (ocisecrets.GetSecretBundleByNameResponse, error) {
	if err := safeEnv(); err != nil {
		return ocisecrets.GetSecretBundleByNameResponse{}, err
	}
	response, err := client.GetSecretBundleByName(ctx, ocisecrets.GetSecretBundleByNameRequest{
		SecretName: new(name), VaultId: new(vaultID), Stage: ocisecrets.GetSecretBundleByNameStageCurrent,
	})
	if err != nil {
		return response, &readError{name: name, cause: err}
	}
	return response, nil
}

// Keep the SDK error available for retry classification, without printing
// a response body that might contain secret material.
type readError struct {
	name  string
	cause error
}

func (e *readError) Error() string    { return "read Vault secret " + e.name + " failed" }
func (e *readError) Unwrap() error    { return e.cause }
func (e *readError) GoString() string { return e.Error() }

func decodeBundle(bundle ocisecrets.SecretBundle, name string) (string, error) {
	var content *string
	switch bundle := bundle.SecretBundleContent.(type) {
	case ocisecrets.Base64SecretBundleContentDetails:
		content = bundle.Content
	case *ocisecrets.Base64SecretBundleContentDetails:
		if bundle != nil {
			content = bundle.Content
		}
	}
	if content == nil {
		return "", fmt.Errorf("Vault secret %s has no base64 content", name)
	}
	if len(*content) > base64.StdEncoding.EncodedLen(maxValue) {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	value, err := base64.StdEncoding.Strict().DecodeString(*content)
	if err != nil {
		return "", fmt.Errorf("Vault secret %s is not base64", name)
	}
	if len(value) > maxValue {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	return string(value), nil
}

func ReadBack(ctx context.Context, client BundleClient, vaultID, name string, created bool) (string, error) {
	for attempt := 1; ; attempt++ {
		value, err := Read(ctx, client, vaultID, name)
		if err == nil || !created || attempt == 30 || !retrySecretRead(err) {
			return value, err
		}
		select {
		case <-ctx.Done():
			return "", ctx.Err()
		case <-time.After(2 * time.Second):
		}
	}
}

func safeEnv() error {
	for _, variable := range ociclient.SecretUnsafeEnv {
		if _, set := os.LookupEnv(variable); set {
			return fmt.Errorf("OCI Vault access refuses to run while %s is set", variable)
		}
	}
	return nil
}

func retrySecretRead(err error) bool {
	var serviceErr common.ServiceError
	if !errors.As(err, &serviceErr) {
		return false
	}
	status := serviceErr.GetHTTPStatusCode()
	return status == http.StatusNotFound || status == http.StatusConflict
}

// Absent reports whether Vault answered that the secret does not exist.
func Absent(err error) bool {
	var serviceErr common.ServiceError
	return errors.As(err, &serviceErr) && serviceErr.GetHTTPStatusCode() == http.StatusNotFound
}
